-- FRM-530 Intermediate Batch Record, FRM-501 "Made as", FSQM-021 v3, and FSQM-016 (draft) corrected.
--
-- Owner, 2026-10-14. The simple syrup the cakes are dunked in is sometimes made on site in the Groen
-- kettle and sometimes bought; the rum is added in the dunk tank and is not kept in the syrup. A lot's
-- syrup and rum are now lines of its lot record (migration 20261014000001). Syrup made on site becomes
-- its own lot, recorded on the new FRM-530 - the sugar and water used, with their supplier lots - so a
-- lot dunked in it traces one step further back. FRM-530 is generic: anything made on site for use in
-- other products. The formula sheet says which kind a product is ("Made as", FRM-501, no revision
-- change, as with the bar code field). FSQM-021 goes to v3 (GJM). FSQM-016 is a draft: three of its
-- lines are brought into line with the floor, and the syrup's growth score is flagged for the team.
--
-- Safe to run twice: every part checks whether it is already done and leaves it alone.

do $$
declare
  n int;
  doc501 uuid;
begin
  -- FRM-530: created once.
  if exists (select 1 from public.sop_documents where sop_number = 'FRM-530') then
    raise notice 'FRM-530 already exists, left alone';
  else
    insert into public.sop_documents
      (sop_number, title, type, category, status, revision, approved_by, effective_date, sqf_reference, sqf_required, content)
    values
      ('FRM-530', 'Intermediate Batch Record', 'form', 'Production', 'active', 'New', 'GJM', '2026-10-14',
       '2.6.1.1, 2.6.2.1, 2.8.1.8', true,
       jsonb_build_object('form_schema', $j${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": false, "instanceTitleTemplate": "{lot_code} - {product}", "batchSheet": {"source": "FRM-501", "productField": "product", "grid": "ingredients", "sourceField": "formula_source", "columns": {"ingredient": "ingredient", "brand": "brand", "expected": "expected_qty", "unit": "unit"}}}, "sections": [{"id": "batch", "title": "1. The batch", "fields": [{"id": "how_this_works", "type": "info", "label": "One entry for each batch made", "text": "For something made on site and used in other products - the simple syrup made in the kettle. Its lot code goes on the container's label, with what it is and the date it was made, and is written on the Production Lot Record (FRM-520) of every lot dunked in it."}, {"id": "product", "type": "text", "label": "Product", "width": "third", "required": true, "showInList": true, "suggestFrom": {"form": "FRM-501", "field": "product_name", "drafts": true}}, {"id": "lot_code", "type": "text", "label": "Lot code", "width": "third", "required": true, "showInList": true, "help": "Filled from the date made: year digit + day of the year, e.g. 6287.", "derive": {"as": "julian_lot", "fromField": "made_on"}}, {"id": "made_on", "type": "date", "label": "Date made", "width": "third", "required": true, "showInList": true}, {"id": "formula_source", "type": "text", "label": "Formula", "width": "half", "help": "Filled in when the entry is started from the formula sheet (FRM-501)."}]}, {"id": "inputs", "title": "2. What went in", "fields": [{"id": "ingredients", "type": "grid", "label": "Ingredients used", "required": true, "scanLabel": true, "help": "One line per supplier lot. If two lots of the same ingredient were used, write two lines.", "rows": {"mode": "dynamic", "min": 1}, "columns": [{"id": "ingredient", "type": "text", "label": "Ingredient", "width": 2, "required": true}, {"id": "brand", "type": "text", "label": "Brand / supplier", "width": 1.5}, {"id": "supplier_lot", "type": "text", "label": "Lot on the container", "width": 1.5, "required": true}, {"id": "expected_qty", "type": "number", "label": "Expected qty", "width": 1, "scanFact": "none"}, {"id": "unit", "type": "select", "label": "Unit", "width": 0.8, "options": ["lb", "oz", "g", "kg", "gal", "fl oz", "each"], "scanFact": "none"}, {"id": "actual_qty", "type": "number", "label": "Weighed", "width": 1, "scanFact": "none", "suggestFrom": {"column": "expected_qty"}}, {"id": "notes", "type": "text", "label": "Notes", "width": 1.5}]}]}, {"id": "kept", "title": "3. Made and kept", "fields": [{"id": "quantity_made", "type": "text", "label": "Quantity made", "width": "third", "maxLength": 60, "help": "For example 5 gal."}, {"id": "use_by", "type": "date", "label": "Use by", "width": "third", "required": true, "showInList": true, "help": "30 days from the date made (FSQM-016).", "derive": {"fromField": "made_on", "addDays": 30, "label": "Use by"}}, {"id": "container_labelled", "type": "checkbox", "label": "The container is sealed and labelled with what it is, its lot code and the date made", "required": true}, {"id": "batch_notes", "type": "textarea", "label": "Notes"}]}, {"id": "signoff", "title": "4. Sign-off", "fields": [{"id": "made_by", "type": "signature", "role": "filler", "label": "Made by", "required": true, "statement": "The lots and quantities in this entry are the ones used."}]}]}$j$::jsonb, 'revision_history', $j$"New - 2026-10-14 - Issued. Approved GJM.\n\nA record of each batch made on site for use in other products - first the simple syrup made in the kettle - so that a lot dunked in it can be traced to the sugar it was made from (FSQM-021 v3; owner, 2026-10-14)."$j$::jsonb));
  end if;

  -- FRM-501: "Made as" after the product name, once.
  select count(*) into n from public.sop_documents where sop_number = 'FRM-501' and status = 'active';
  if n <> 1 then raise exception 'FRM-501: expected one active document, found %', n; end if;
  select id into doc501 from public.sop_documents where sop_number = 'FRM-501' and status = 'active';
  if exists (select 1 from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
                    jsonb_array_elements(s->'fields') f where d.id = doc501 and f->>'id' = 'made_as') then
    raise notice 'FRM-501 already has Made as, left alone';
  elsif not exists (select 1 from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
                    jsonb_array_elements(s->'fields') f where d.id = doc501 and f->>'id' = 'product_name') then
    raise exception 'FRM-501 has no product_name field';
  else
    update public.sop_documents d
       set content = jsonb_set(d.content, '{form_schema,sections}', (
             select jsonb_agg(
                      jsonb_set(s, '{fields}', coalesce((
                        select jsonb_agg(x.f order by x.k)
                          from (select f, (fo * 2)::int as k from jsonb_array_elements(s->'fields') with ordinality as z(f, fo)
                                union all
                                select $j${"id": "made_as", "type": "select", "label": "Made as", "options": ["Finished product", "Made on site for use in other products"], "help": "Made on site for use in other products (the simple syrup): a batch of it is recorded on FRM-530, not on the Production Lot Record. Blank means a finished product."}$j$::jsonb, (fo * 2 + 1)::int from jsonb_array_elements(s->'fields') with ordinality as z(f, fo)
                                 where f->>'id' = 'product_name') x
                      ), '[]'::jsonb))
                      order by so)
               from jsonb_array_elements(d.content->'form_schema'->'sections') with ordinality as y(s, so)
           ))
     where d.id = doc501;
  end if;

  -- FSQM-021 v2 -> v3, only from the v2 text this was written against.
  if exists (select 1 from public.sop_documents where sop_number = 'FSQM-021' and status = 'active' and revision = 'v3') then
    raise notice 'FSQM-021 is already v3, left alone';
  elsif not exists (select 1 from public.sop_documents where sop_number = 'FSQM-021' and status = 'active' and revision = 'v2'
                     and md5((content->'procedure')::text) = '476d67bddf83c1055652dabec3fe02e0') then
    raise exception 'FSQM-021 is not the v2 text this migration was written against';
  else
    update public.sop_documents
       set revision = 'v3', effective_date = '2026-10-14', approved_by = 'GJM',
           content = content || jsonb_build_object(
             'procedure', $j$["Identification at every stage", "• Receipt: every delivery is logged on FRM-301 with the supplier, the material, the supplier lot and the date received. Material that arrives without a readable lot code or label is held on FRM-702 until the supplier identifies it (SQF 2.6.1.1 i, 2.6.2.1 ii).", "• Storage: every ingredient, processing aid and packaging material stays in the bag, box, pail or roll it arrived in, with the supplier's label and lot, until it is used up. A part-used bag is closed and kept in its own bag. Nothing is decanted into another container (SQF 2.6.1.1 i).", "• Production: ingredients are weighed straight from their original containers, so the supplier lot is in front of the person using it. Batter is deposited in the run it is mixed for and is never stored (SQF 2.6.1.1 i).", "• Syrup made on site is made as its own lot and recorded on FRM-530 (Intermediate Batch Record): the sugar and the water used, with the supplier lot of each, and a lot code for the syrup in the same form as the product's, from the day it was made. Its container is labelled with what it is, its lot code and the date it was made, and the syrup is used within 30 days of being made (FSQM-016). The rum is not kept in the syrup: it is added in the dunk tank (SQF 2.6.1.1 i).", "• Baked product cooling on racks carries a rack card with the product and its lot code until it is wrapped (SQF 2.6.1.1 i).", "• Finished product: every pack is coded with the lot code and best-by date on the coder (SOP-603, SOP-604) and labelled to its specification on FRM-704 and to US labelling law. The label and code are checked before release on FRM-701 under FSQM-020 (SQF 2.6.1.1 ii).", "• Product put on hold is identified by its FRM-702 hold tag, and a retention sample by its FRM-703 entry, each carrying the lot code.", "• A cake is taken out of the run, without a tag, when it breaks at depanning, is plainly too big or too small after baking, or is oversoaked in the syrup. These are ordinary losses in production, not held product. Each is set aside from good product, counted, and included in the units not packed on FRM-520. The lot's retention sample may be taken from them - a cake that is too big or too small will do, an oversoaked one will not - or from good product. Whichever it is, the sample is soaked and sealed like the rest of the lot and logged on FRM-703. Cakes not kept as a sample leave as food waste under FSQM-037. The hold tag is for product whose safety or quality is in question, not for these.", "The lot code", "• The lot code is the last digit of the year and the three-digit day of the year on which the product was BAKED, for example 6272. It is the same code written on FRM-507 for that day's oven loads.", "• When wrapping runs into the next day, the coder is set to the bake day's code, not to the day of wrapping. A product baked on day 272 is 6272 whenever it is packed.", "• One lot is one product baked on one day. If the same product is baked on two days, it is two lots.", "The Production Lot Record - the cross reference", "• For each product baked each day, a Production Lot Record is kept on FRM-520 as the product is made - filled in directly in the Team Portal, or written on the printed prep sheet on the floor and entered within one working day (SQF 2.6.2.1 i).", "• The record carries the product, its lot code and the bake date, and a line for every ingredient used with the supplier lot printed on its container. If two lots of the same ingredient are used, both are written down.", "• Processing aids are listed like ingredients - in particular the pan spray, which contains soy - so that every allergen-bearing input can be traced back (SQF 2.8.1.8).", "• The syrup and the rum the cake is dunked in are listed too, with the lot on each container - the supplier's lot, or for syrup made on site its FRM-530 lot code. On the formula sheet (FRM-501) these lines are marked as added at dunking, and their lots are written when the lot is dunked, after baking and before sealing. If a second container of either is opened during dunking, both lots are written down (SQF 2.6.2.1).", "• If rework is used, it is recorded with its own original lot code, so a lot made with rework traces back through the rework to its supplier lots (SQF 2.6.2.1 iii).", "• At wrapping, the record takes the pack date and the number of units packed. The film or vacuum bag touches the cake and is food-contact packaging: its lot is written when the maker prints one, and when none is printed the date that film was received is written instead, which FRM-301 ties to its supplier. The boxes the sealed cakes go into are outer packaging and are not traced (SQF 2.6.2.1 ii).", "• Whichever way it is filled in, the FRM-520 entry is the record. A photo of a paper prep sheet may be attached to it but is not required; a paper sheet that was used is kept with the batch records under SOP-2.2.3 (SQF 2.6.2.1).", "Start-up, changeover and the label", "> Every rum cake is packed in the same box. The ingredient list and the allergen statement are printed on that box and are the same for every flavor. What changes from one product to the next is what the coder prints on the box at packing: the company name, the flavor, the lot code, the best-by date and the bar code. Putting the right label on a product therefore means loading the right coder message.", "> Product wrapped in printed film - the biscotti - is different. Each variety has its own film, with its own ingredient list and allergen statement printed on it, and the coder adds only the lot code and the best-by date. There, putting the right label on the product means loading the right roll of film, and a wrong roll is a wrong allergen statement.", "• At the start of packing, and every time the product changes, the person packing loads the coder message for that product - and, where the product is wrapped in printed film, the roll for that variety - and makes one pack (SOP-603, SOP-604, SOP-605).", "• That first pack is checked against the Production Lot Record before packing carries on: the flavor or variety on the pack is the product being packed; on printed film, the film is the one for that variety, with its allergen statement; the lot code and best-by date are right; and any bar code scans. Production staff trained on the coder and the wrapper are authorized to approve it. The result and the name of the person who checked are written on FRM-520 (SQF 2.6.1.2, 2.8.1.9).", "• The check is made again whenever the coder is restarted or its message is edited, and whenever a new roll of film is loaded during the run.", "• Before the next product is packed, boxes already printed for the one before are taken off the packing table, the film of the variety before is taken off the wrapper and put back with its own kind, and any other packaging that belongs only to that product is removed (SQF 2.6.1.2).", "• No pre-printed label is issued by count, so what is reconciled is the product. The cakes are counted when they go on the baking rack. At the end of packing that count is compared with the units packed plus the units not packed - broken at depanning, the wrong size, oversoaked, otherwise rejected or damaged, or kept as the retention sample - and all three figures are written on FRM-520. A difference that cannot be explained is settled before the lot is released, and raised on FRM-007 if it cannot be (SQF 2.6.1.2).", "• Before packing ends, three finished packs from the lot are weighed, each one whole, on a scale that is in the calibration program (FSQM-030), and the three weights are written on FRM-520 with the net weight on the label and the weight of the empty packaging. With the empty packaging taken off, their average is at or above the net weight on the label. If it is not, packing stops and the lot is held on FRM-702 until the SQF Practitioner decides (FSQM-020, SQF 2.4.1.1).", "• A product goes into a printed box or a printed film only if the ingredients and allergens of its formula are the ones printed on it. That is checked on FRM-601 before a new or changed product is first packed, and the change is assessed first under FSQM-007 (SQF 2.8.1.9).", "• When a printed box, a printed film or a coder message is replaced, the old boxes or film are taken out of use, counted and disposed of under FSQM-037, and the old message is deleted from the coder. Both are noted on the FRM-601 for the new version (SQF 2.8.1.9).", "• The label and the code are looked at once more, by the SQF Practitioner, when the lot is released on FRM-701.", "Tracing", "• One step back: from a finished lot code, FRM-520 gives every supplier lot used, and FRM-301 gives the supplier and the date each was received (SQF 2.6.2.1 i, ii). Syrup made on site is followed one step further: its FRM-530 entry gives the supplier lots it was made from.", "• One step forward: from a finished lot code, FRM-801 gives every customer who collected it, how much and when (SQF 2.6.2.1 i).", "• From a supplier lot - for example a supplier's recall or allergen notice - the FRM-520 entries that list it give every finished lot it went into, and FRM-801 gives where those lots went. A supplier lot used in syrup made on site is found on FRM-530 first, and the FRM-520 entries that list that syrup's lot give the finished lots (SQF 2.8.1.8).", "Testing the trace", "• At least once a year, the SQF Practitioner picks a finished lot and traces it both ways from the records alone: back to every supplier lot and its receipt on FRM-301, and forward to every customer on FRM-801 (SQF 2.6.2.1 iv).", "• The test passes when every input is traced to a supplier lot and a receipt, and the quantity packed is accounted for - collected by customers, still on site, retained on FRM-703, or disposed of on FRM-702. Any gap is raised as a CAPA on FRM-007 under FSQM-009.", "• The trace test is part of the annual product recall and withdrawal test and is reviewed with it (SQF 2.6.2.1 iv).", "Records", "• FRM-301, FRM-520, FRM-530, FRM-507, FRM-701 and FRM-801 are the trace records. They are kept for at least two years, as SOP-2.2.3 requires (SQF 2.6.2.1)."]$j$::jsonb,
             'records', $j$"• FRM-520 entries, one per product per bake day, carrying the first-box check, the count reconciliation and the three pack weights; any paper prep sheets used, filed with the batch records\n• FRM-530 entries, one for each batch of syrup made on site\n• FRM-301 receiving entries\n• FRM-507, FRM-701 and FRM-801 entries carrying the lot code\n• The annual trace test"$j$::jsonb,
             'form_references', $j$"FRM-520 - Production Lot Record\nFRM-530 - Intermediate Batch Record\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-507 - CCP 1 Baking Monitoring Record\nFRM-701 - Finished Product Release Record\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-703 - Retention Sample Log\nFRM-704 - Finished Product Specification\nFRM-007 - Corrective & Preventive Action (CAPA) Report\nFRM-601 - Label Review & Approval Form"$j$::jsonb,
             'revision_history', $j$"New - 2026-09-29 - DRAFT under D-20, for the three Minor findings against 2.6.1.1, 2.6.2.1 and 2.8.1.8. Written as one program; the workbook's separate SOP-2.6.2 is not needed.\n\nWHAT THE SITE DOES (owner, 2026-09-29): the lot code is the last digit of the year and the day of the year, e.g. 6272, as SOP-2.2.3 already states; it is the BAKE day. Ingredients are weighed out of the bags and containers they arrived in; nothing is decanted. All product goes to business customers and is collected. Supplier lots are recorded at receipt on FRM-301 and the lot and customer at dispatch on FRM-801.\n\nNEW WITH THIS PROGRAM: the Production Lot Record, FRM-520 - filled in directly in the Team Portal or from the printed prep sheet - which is the cross reference between the supplier lots used and our lot code. Before this, nothing recorded which supplier lots went into which lot. Also new: the coder is set to the bake day when wrapping runs into the next day, and the annual trace test.\n\nTHE TRACE TEST'S RECORD arrives with the recall and withdrawal program (D-21), as 2.6.2.1 iv ties the two together; the 'traceability test' row on the verification schedule stays planned until then.\n\nTO CONFIRM BEFORE ISSUE: (1) the rack card for baked product cooling on racks - product and lot code; (2) how syrup made ahead is identified while stored - open under D-14; (3) whether the coder is set to the bake day today when wrapping runs over, or whether that is new practice.\n\nRENUMBERED 2026-09-30: the Production Lot Record is FRM-520, not FRM-510, so it is not mistaken for FRM-501 Formula Sheet & Batch Data.\n\nPAPER OPTIONAL 2026-09-30 (owner): the site will not be forced onto paper. FRM-520 can be filled in directly; the printed prep sheet is an option, and a photo of it may be attached but is not required. The required 'Paper sheet - photo attached' question was removed from FRM-520.\n\nCHANGEOVER AND LABEL CONTROL ADDED 2026-10-06 (still a draft), for what D-17 left open: 2.6.1.2 and 2.8.1.9. Written into this program and FRM-520, with no new document and no new form.\n\nWHAT THE SITE DOES (owner, 2026-10-06): every rum cake goes into the same box, with one printed ingredient list and allergen statement for all flavors. An ink-jet coder prints the company name, flavor, lot code, best-by date and bar code on the box just after the cake goes in, so there is no stock of pre-printed labels to issue, clear or count. The first printed box is already looked at, but nothing was written down. The cakes are counted on the baking rack and the packed cakes are bulk packed 48 to a case, but the two counts were never compared. No artwork has changed yet, so there has been no obsolete packaging.\n\nNEW WITH THIS CHANGE: the first-box check is recorded on FRM-520 with who made it; the rack count, the units packed and the units not packed are written on FRM-520 and compared; the rule that a product may only go into the printed box if its formula matches what is printed on it; and what happens to old boxes and coder messages when artwork changes.\n\nONE PERSON PACKS. The program does not pretend there is a separate supervisor: production staff trained on the coder approve the first box, and the SQF Practitioner sees the label and code again at release on FRM-701.\n\nTO CONFIRM BEFORE ISSUE: (4) that every flavor's formula matches the one ingredient list and allergen statement printed on the box - an FRM-601 review per flavor; (5) how products packed in another customer's packaging are labelled, and whether the same first-box check applies to them.\n\nORDINARY LOSSES 2026-10-06 (owner and SQF Practitioner): a cake often breaks into pieces at depanning; a cake that is plainly too big or too small after baking is removed; and a cake oversoaked at dunking is removed. They are set aside and counted as waste; tagging each one on FRM-702 is not reasonable and was never the intent. The retention sample MAY be one of them (an off-size cake, never an oversoaked one) or a good cake - it is a choice, not a rule - and is soaked and sealed like the rest of the lot either way; cakes not kept leave as food waste. The line that said rejected product is identified by a hold tag now covers held product and retention samples only, and a new line says these ordinary losses is counted as not packed on FRM-520 and leaves as food waste. FRM-520's 'Not packed' help line names them.\n\nPRINTED FILM 2026-10-06 (owner). The two points listed to confirm are answered. (4) Every rum cake flavor's formula matches the one ingredient list printed on the box. (5) The only other product packed here is the biscotti, which is baked on site and flow-wrapped in printed film: each variety has its own film carrying everything but the lot code and best-by date, which the coder prints. The first pack is already looked at, unrecorded. The Part now covers printed film: the roll for the variety is part of the first-pack check, the check is repeated when a new roll is loaded, and the previous variety's film comes off the wrapper at changeover. Old packaging is 'disposed of under FSQM-037', not 'destroyed', because that program decides which printed packaging has to be defaced.\n\nISSUED 2026-10-06, with FRM-520. What the draft listed to confirm (owner, 2026-10-06): (1) RACK CARD - a card with the product and lot code is used on racks of cooling product, as written. (2) SYRUP - syrup made ahead is kept in a labelled container; a line saying so is added under Identification at every stage. (3) CODER - when wrapping runs into the next day the coder is set to the bake day's code, as written. (4) and (5) were answered the same day and are recorded above. The record of the annual trace test arrives with the recall and withdrawal program, so the 'traceability test' row on the verification schedule stays planned until that program is issued.\n\nv2 - 2026-10-12 - Three finished packs are weighed at packing. Approved GJM.\n\nThe Part 'Start-up, changeover and the label' gains one line: before packing ends, three finished packs are weighed and the weights written on FRM-520 (v2), with the lot held on FRM-702 if their average net weight is below the label. The weighing was done at release until now (FSQM-020 v4; owner's decision, 2026-10-12). Records names the pack weights. Nothing else changes.\n\nv3 - 2026-10-14 - Dunking ingredients and syrup made on site. Approved GJM.\n\nIdentification: syrup made on site becomes its own lot, recorded on the new FRM-530 Intermediate Batch Record with the supplier lots of the sugar and water, labelled with its lot code and used within 30 days; the rum is added in the dunk tank and is not kept in the syrup. The Production Lot Record lists the syrup and the rum each lot is dunked in, with their lots, marked on the formula sheet as added at dunking (owner, 2026-10-14). Tracing follows syrup made on site one step further, to its supplier lots. FRM-530 is added to the trace records and the linked forms."$j$::jsonb)
     where sop_number = 'FSQM-021' and status = 'active';
  end if;

  -- FSQM-016 (draft), line 1: replaced only where the old line still stands.
  update public.sop_documents
     set content = jsonb_set(content, '{procedure}', (
           select jsonb_agg(case when l = $t$◦ B - Yeasts, molds or bacteria growing in syrup kept for a later run: L2 × S2 = 4, not significant. The syrup is two parts sugar to one part water, with rum added: a concentrated sugar syrup with alcohol, in which food-poisoning bacteria are not expected to grow. Its own water activity has not been measured and the amount of rum is not recorded here. Kept so by the hold rule below.$t$ then to_jsonb($t$◦ B - Yeasts, molds or bacteria growing in syrup kept for a later run: L2 × S2 = 4, not significant. The syrup is two parts sugar to one part water; the rum is added in the dunk tank and is not in syrup kept for a later run (corrected 2026-10-14 - this score was first written for a syrup with alcohol in it, and is for the food safety team to confirm). A concentrated sugar syrup, in which food-poisoning bacteria are not expected to grow. Its own water activity has not been measured. Kept so by the hold rule below.$t$::text) else to_jsonb(l) end order by o2)
             from jsonb_array_elements_text(content->'procedure') with ordinality as p(l, o2)))
   where sop_number = 'FSQM-016' and status = 'draft'
     and exists (select 1 from jsonb_array_elements_text(content->'procedure') l where l = $t$◦ B - Yeasts, molds or bacteria growing in syrup kept for a later run: L2 × S2 = 4, not significant. The syrup is two parts sugar to one part water, with rum added: a concentrated sugar syrup with alcohol, in which food-poisoning bacteria are not expected to grow. Its own water activity has not been measured and the amount of rum is not recorded here. Kept so by the hold rule below.$t$);

  -- FSQM-016 (draft), line 2: replaced only where the old line still stands.
  update public.sop_documents
     set content = jsonb_set(content, '{procedure}', (
           select jsonb_agg(case when l = $t$◦ SYRUP HOLD RULE. Prepared syrup is kept sealed, at room temperature, for no more than 30 days from the day it was made; it is normally used within a few days. The container is labelled with the date made and a lot code in the same form as the product's - the last digit of the year and the three-digit day of the year. Syrup that is past 30 days, unlabelled, or showing gas, cloudiness, mold or an off smell is discarded.$t$ then to_jsonb($t$◦ SYRUP HOLD RULE. Prepared syrup is kept sealed, at room temperature, for no more than 30 days from the day it was made; it is normally used within a few days. The container is labelled with the date made and a lot code in the same form as the product's - the last digit of the year and the three-digit day of the year. Syrup that is past 30 days, unlabelled, or showing gas, cloudiness, mold or an off smell is discarded. Each batch made is recorded on FRM-530, with the supplier lots of the sugar used.$t$::text) else to_jsonb(l) end order by o2)
             from jsonb_array_elements_text(content->'procedure') with ordinality as p(l, o2)))
   where sop_number = 'FSQM-016' and status = 'draft'
     and exists (select 1 from jsonb_array_elements_text(content->'procedure') l where l = $t$◦ SYRUP HOLD RULE. Prepared syrup is kept sealed, at room temperature, for no more than 30 days from the day it was made; it is normally used within a few days. The container is labelled with the date made and a lot code in the same form as the product's - the last digit of the year and the three-digit day of the year. Syrup that is past 30 days, unlabelled, or showing gas, cloudiness, mold or an off smell is discarded.$t$);

